/**
 * @brief: metaGDB dual-mode entry: REPL interactive mode (default) and Demo demonstration mode.
 *
 * This file is the stable entry point of the framework body, independent of any specific
 * implementation crate. Implementation selection is encapsulated in the metagdb::assembly
 * module (where the active submodule is generated by scripts/build.py based on
 * implementation/manifest.toml).
 *
 * Usage:
 *   cargo run              → REPL interactive mode (data persists to target/data/)
 *   cargo run -- --demo    → Demo demonstration mode (loads preset data, runs example queries then exits)
 *   cargo run -- --benchmark benchmark/<language> → Fixed external conformance benchmark
 *   cargo run -- --system-benchmark ... → Fixed ACID/storage/registration benchmark
 *   cargo run --release -- --micro-benchmark ... → Fixed single-thread performance benchmark
 */
use std::env;
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;

use metagdb::assembly;
use metagdb_core::common::property::{PropertyValue, ResultValue};
use metagdb_core::l4_compute::engine::ResultStream;
use metagdb_core::Result;

mod benchmark;
mod canon;
mod json;
mod performance_benchmark;
mod system_benchmark;

/// REPL mode data directory
const REPL_DATA_DIR: &str = "target/data";

// ============================================================
// Entry
// ============================================================

/**
 * @brief: Program entry point, dispatches to Demo / Build / REPL mode based on command-line
 *         arguments.
 * @return: Returns Ok(()) on success, or an error otherwise.
 */
fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    let mode = if let Some(pos) = args.iter().position(|a| a == "--benchmark-child") {
        Mode::BenchmarkChild {
            request: PathBuf::from(required_arg(
                &args,
                pos + 1,
                "--benchmark-child requires a request path",
            )?),
            response: PathBuf::from(required_arg(
                &args,
                pos + 2,
                "--benchmark-child requires a response path",
            )?),
            data_dir: PathBuf::from(required_arg(
                &args,
                pos + 3,
                "--benchmark-child requires a data directory",
            )?),
        }
    } else if args.iter().any(|a| a == "--micro-benchmark") {
        let repeat = option_value(&args, "--repeat")?
            .parse::<usize>()
            .map_err(|_| {
                metagdb_core::Error::Other("--repeat must be a positive integer".into())
            })?;
        Mode::MicroBenchmark(performance_benchmark::Config {
            dataset: option_value(&args, "--dataset")?,
            graph: PathBuf::from(option_value(&args, "--graph")?),
            repeat,
            output: PathBuf::from(option_value(&args, "--output")?),
            algorithm_plan: optional_value(&args, "--algorithm-plan").map(PathBuf::from),
            revision: optional_value(&args, "--revision").unwrap_or_default(),
            design_sha: optional_value(&args, "--design-sha").unwrap_or_default(),
            graph_sha: optional_value(&args, "--graph-sha").unwrap_or_default(),
            point_query_template: option_value(&args, "--point-query-template")?,
            one_hop_query_template: option_value(&args, "--one-hop-query-template")?,
            reuse_data: args.iter().any(|value| value == "--reuse-data"),
            edge_insert_window: args.iter().any(|value| value == "--edge-insert-window"),
        })
    } else if let Some(pos) = args.iter().position(|a| a == "--system-benchmark-child") {
        let scenario = required_arg(
            &args,
            pos + 1,
            "--system-benchmark-child requires a scenario",
        )?;
        let data_dir = PathBuf::from(required_arg(
            &args,
            pos + 2,
            "--system-benchmark-child requires a data directory",
        )?);
        let isolation = system_benchmark::parse_isolation(&required_arg(
            &args,
            pos + 3,
            "--system-benchmark-child requires an isolation level",
        )?)?;
        Mode::SystemBenchmarkChild {
            scenario,
            data_dir,
            isolation,
        }
    } else if args.iter().any(|a| a == "--system-benchmark") {
        let isolation = system_benchmark::parse_isolation(&option_value(&args, "--isolation")?)?;
        let concurrency_control = option_value(&args, "--concurrency-control")?;
        let durability = match option_value(&args, "--durability")?.as_str() {
            "restart" => system_benchmark::Durability::Restart,
            "crash_safe" => system_benchmark::Durability::CrashSafe,
            value => {
                return Err(metagdb_core::Error::Other(format!(
                    "unsupported durability: {value}"
                )))
            }
        };
        let schema_mode =
            system_benchmark::parse_schema_mode(&option_value(&args, "--schema-mode")?)?;
        let vertex_labels = csv_option(&args, "--vertex-labels")?;
        let edge_types = csv_option(&args, "--edge-types")?;
        let property_keys = csv_option(&args, "--property-keys")?;
        let required_algorithms = option_value(&args, "--required-algorithms")?
            .split(',')
            .filter(|x| !x.is_empty())
            .map(str::to_owned)
            .collect();
        Mode::SystemBenchmark(system_benchmark::Config {
            isolation,
            concurrency_control,
            durability,
            schema_mode,
            vertex_labels,
            edge_types,
            property_keys,
            required_algorithms,
            diagnostic: args.iter().any(|a| a == "--diagnostic"),
        })
    } else if let Some(pos) = args.iter().position(|a| a == "--benchmark") {
        let dataset_dir = args.get(pos + 1).map(PathBuf::from).ok_or_else(|| {
            metagdb_core::Error::Other("--benchmark requires a dataset directory".into())
        })?;
        let min_pass_rate = rate_option(&args, "--min-pass-rate")?.unwrap_or(0.9);
        let min_execution_rate = rate_option(&args, "--min-execution-rate")?.unwrap_or(0.0);
        let (shard, shards) = shard_option(&args)?;
        Mode::Benchmark(benchmark::Config {
            dataset_dir,
            fixtures_path: optional_value(&args, "--fixtures").map(PathBuf::from),
            min_pass_rate,
            timeout_ms: unsigned_option(&args, "--timeout-ms")?.unwrap_or(0),
            output_dir: optional_value(&args, "--output-dir")
                .map(PathBuf::from)
                .unwrap_or_else(|| PathBuf::from("target/benchmark-run")),
            id_filter: optional_value(&args, "--filter"),
            capabilities: optional_values(&args, "--capability"),
            min_execution_rate,
            strict_fixtures: !args.iter().any(|a| a == "--lenient-fixtures"),
            shard,
            shards,
            resume: args.iter().any(|a| a == "--resume"),
            quiet: args.iter().any(|a| a == "--quiet"),
        })
    } else if let Some(pos) = args.iter().position(|a| a == "--build") {
        let graph_file = args.get(pos + 1).map(PathBuf::from).ok_or_else(|| {
            metagdb_core::Error::Storage("--build requires a .graph file path".into())
        })?;
        Mode::Build { graph_file }
    } else if args.iter().any(|a| a == "--demo") {
        Mode::Demo
    } else {
        Mode::Repl
    };

    match mode {
        Mode::BenchmarkChild {
            request,
            response,
            data_dir,
        } => benchmark::run_child(&request, &response, &data_dir),
        Mode::Demo => run_demo(),
        Mode::Repl => run_repl(),
        Mode::Build { graph_file } => run_build(&graph_file),
        Mode::Benchmark(config) => benchmark::run(config),
        Mode::SystemBenchmark(config) => system_benchmark::run(config),
        Mode::MicroBenchmark(config) => performance_benchmark::run(config),
        Mode::SystemBenchmarkChild {
            scenario,
            data_dir,
            isolation,
        } => system_benchmark::run_crash_child(&scenario, &data_dir, isolation),
    }
}

fn required_arg(args: &[String], index: usize, message: &str) -> Result<String> {
    args.get(index)
        .cloned()
        .ok_or_else(|| metagdb_core::Error::Other(message.into()))
}

fn option_value(args: &[String], name: &str) -> Result<String> {
    let pos = args
        .iter()
        .position(|value| value == name)
        .ok_or_else(|| metagdb_core::Error::Other(format!("missing required option {name}")))?;
    required_arg(args, pos + 1, &format!("{name} requires a value"))
}

fn optional_value(args: &[String], name: &str) -> Option<String> {
    args.iter()
        .position(|value| value == name)
        .and_then(|position| args.get(position + 1))
        .cloned()
}

fn csv_option(args: &[String], name: &str) -> Result<Vec<String>> {
    Ok(option_value(args, name)?
        .split(',')
        .filter(|item| !item.is_empty())
        .map(str::to_owned)
        .collect())
}

/// Read a repeatable flag, e.g. `--capability core --capability advanced`.
fn optional_values(args: &[String], name: &str) -> Vec<String> {
    args.iter()
        .enumerate()
        .filter(|(_, value)| value.as_str() == name)
        .filter_map(|(index, _)| args.get(index + 1))
        .filter(|value| !value.starts_with("--"))
        .cloned()
        .collect()
}

fn rate_option(args: &[String], name: &str) -> Result<Option<f64>> {
    match optional_value(args, name) {
        None => Ok(None),
        Some(text) => {
            let value = text.parse::<f64>().map_err(|_| {
                metagdb_core::Error::Other(format!("{name} must be a number between 0 and 1"))
            })?;
            if !(0.0..=1.0).contains(&value) {
                return Err(metagdb_core::Error::Other(format!(
                    "{name} must be between 0 and 1"
                )));
            }
            Ok(Some(value))
        }
    }
}

fn unsigned_option(args: &[String], name: &str) -> Result<Option<u64>> {
    match optional_value(args, name) {
        None => Ok(None),
        Some(text) => text
            .parse::<u64>()
            .map(Some)
            .map_err(|_| metagdb_core::Error::Other(format!("{name} must be a positive integer"))),
    }
}

/// Parse `--shard <index>/<count>`.
fn shard_option(args: &[String]) -> Result<(usize, usize)> {
    match optional_value(args, "--shard") {
        None => Ok((0, 1)),
        Some(text) => {
            let (index, count) = text.split_once('/').ok_or_else(|| {
                metagdb_core::Error::Other("--shard must be written as <index>/<count>".into())
            })?;
            let index: usize = index.trim().parse().map_err(|_| {
                metagdb_core::Error::Other("--shard index must be an integer".into())
            })?;
            let count: usize = count.trim().parse().map_err(|_| {
                metagdb_core::Error::Other("--shard count must be an integer".into())
            })?;
            if count == 0 || index >= count {
                return Err(metagdb_core::Error::Other(
                    "--shard requires 0 <= index < count".into(),
                ));
            }
            Ok((index, count))
        }
    }
}

/// Run mode
enum Mode {
    /// Internal process-isolated language benchmark case.
    BenchmarkChild {
        request: PathBuf,
        response: PathBuf,
        data_dir: PathBuf,
    },
    /// REPL interactive mode (default)
    Repl,
    /// Demo demonstration mode (--demo)
    Demo,
    /// Build batch import mode (--build <file>)
    Build { graph_file: PathBuf },
    /// Run the graded Core Language Profile (--benchmark <dataset-dir>)
    Benchmark(benchmark::Config),
    /// Run the fixed language-independent ACID/storage/algorithm benchmark.
    SystemBenchmark(system_benchmark::Config),
    /// Run fixed single-thread storage and end-to-end performance workloads.
    MicroBenchmark(performance_benchmark::Config),
    /// Internal abrupt-exit helper used by crash recovery cases.
    SystemBenchmarkChild {
        scenario: String,
        data_dir: PathBuf,
        isolation: metagdb_core::l3_txn::IsolationLevel,
    },
}

// ============================================================
// Demo Mode
// ============================================================

/**
 * @brief: Execute Demo demonstration mode: delegates to the implementation crate's demo_test()
 *         end-to-end test entry.
 *
 * demo_test() is provided by the implementation crate (LLM-generated or hand-written), and
 * internally self-contains: create Runtime → insert demo data → execute test queries one by one
 * → verify output → print results. The framework body no longer contains any query-language-
 * specific hardcoded logic, compatible with all query languages.
 *
 * @return: Returns Ok(()) on success, or an error otherwise.
 */
fn run_demo() -> Result<()> {
    println!("=== metaGDB demo ===");
    assembly::run_demo_test()?;
    println!("=== demo done ===");
    Ok(())
}

// ============================================================
// Build Mode
// ============================================================

/**
 * @brief: Execute Build batch import mode: reads a .graph file and creates a database.
 *
 * The database name is derived from the .graph file stem, and data persists to
 * target/data/<stem>/. Prints a summary and exits after import completes.
 *
 * @param graph_file: Path to the .graph file.
 * @return: Returns Ok(()) on success, or an error otherwise.
 */
fn run_build(graph_file: &Path) -> Result<()> {
    // Verify .graph file exists
    if !graph_file.exists() {
        return Err(metagdb_core::Error::Storage(format!(
            "Graph file does not exist: {}",
            graph_file.display()
        )));
    }

    // Derive database name from file stem
    let db_name = graph_file
        .file_stem()
        .and_then(|s| s.to_str())
        .ok_or_else(|| metagdb_core::Error::Storage("Invalid .graph filename".into()))?;
    let data_dir = format!("target/data/{}", db_name);

    println!("=== metaGDB build ===");
    println!("Graph file: {}", graph_file.display());
    println!("Database directory: {}", data_dir);

    match assembly::build_from_graph_file(graph_file, &data_dir) {
        Ok(runtime) => {
            println!("Database built successfully.");
            println!("=== build done ===");
            println!();
            // After build succeeds, enter interactive command line, reusing the Runtime with
            // loaded data
            run_repl_with_runtime(&data_dir, runtime)
        }
        Err(e) => {
            eprintln!("Build failed: {}", e);
            Err(e)
        }
    }
}

// ============================================================
// REPL Mode
// ============================================================

/**
 * @brief: Start REPL interactive mode (using default data directory).
 *
 * @return: Returns Ok(()) on success, or an error otherwise.
 */
fn run_repl() -> Result<()> {
    run_repl_with_dir(REPL_DATA_DIR)
}

/**
 * @brief: Start REPL interactive mode (using specified data directory).
 *
 * In a loop, reads user-entered Cypher statements or meta-commands, executes them, and outputs
 * results. Data persists to the specified data_dir directory.
 *
 * @param data_dir: Path to the data file storage directory.
 * @return: Returns Ok(()) on success, or an error otherwise.
 */
fn run_repl_with_dir(data_dir: &str) -> Result<()> {
    // Ensure data directory exists
    let data_dir_path = Path::new(data_dir);
    if !data_dir_path.exists() {
        std::fs::create_dir_all(data_dir_path).map_err(|e| {
            metagdb_core::Error::Storage(format!(
                "Cannot create data directory {}: {}",
                data_dir, e
            ))
        })?;
    }

    let runtime = assembly::build_runtime_clean(data_dir)?;
    run_repl_with_runtime(data_dir, runtime)
}

/**
 * @brief: Start REPL interactive mode using a pre-built Runtime.
 *
 * Used for build mode: after batch import, the Runtime holding the loaded data is not discarded;
 * instead it directly enters REPL querying. This is particularly critical for in-memory storage
 * engines — data is only held within the Runtime, and reconstructing the Runtime would cause
 * data loss.
 *
 * @param data_dir: Path to the data file directory (for display).
 * @param runtime: A fully constructed Runtime instance.
 * @return: Returns Ok(()) on success, or an error otherwise.
 */
fn run_repl_with_runtime(data_dir: &str, runtime: metagdb::pipeline::Runtime) -> Result<()> {
    println!("=== metaGDB REPL ===");
    println!("Language: {:?}", runtime.default_language());
    println!("Data directory: {}", data_dir);
    println!("Enter :help for help, :quit to exit");
    println!();

    let stdin = io::stdin();
    let mut reader = stdin.lock();
    let mut line = String::new();
    let mut buffer = String::new(); // Multi-line accumulation buffer

    loop {
        // Prompt: continuation indicator shown in accumulation mode
        if buffer.is_empty() {
            print!("metaGDB> ");
        } else {
            print!("       → ");
        }
        io::stdout().flush().ok();

        line.clear();
        match reader.read_line(&mut line) {
            Ok(0) => {
                // EOF (Ctrl+D)
                println!();
                break;
            }
            Ok(_) => {}
            Err(e) => {
                eprintln!("Failed to read input: {}", e);
                break;
            }
        }

        let trimmed = line.trim();

        // Empty line: if there is accumulated content, submit for execution; otherwise ignore
        if trimmed.is_empty() {
            if !buffer.is_empty() {
                // Submit accumulated query
                execute_buffered(&mut buffer, &runtime);
            }
            continue;
        }

        // Meta commands are only recognized when buffer is empty (line starts with ':')
        if buffer.is_empty() && trimmed.starts_with(':') {
            if handle_meta_command(trimmed, &runtime) == ReplAction::Quit {
                break;
            }
            continue;
        }

        // Append to accumulation buffer
        buffer.push_str(trimmed);
        buffer.push(' ');

        // If line ends with semicolon, submit for execution
        if trimmed.ends_with(';') {
            execute_buffered(&mut buffer, &runtime);
        }
    }

    println!("Goodbye.");
    Ok(())
}

/// REPL loop control
#[derive(PartialEq, Eq)]
enum ReplAction {
    Continue,
    Quit,
}

/**
 * @brief: Execute the query accumulated in the buffer and clear the buffer.
 *
 * Removes the trailing semicolon, executes, and prints result or error.
 *
 * @param buffer: Accumulated query text (mutable reference, cleared after execution).
 * @param runtime: The current runtime.
 */
fn execute_buffered(buffer: &mut String, runtime: &metagdb::pipeline::Runtime) {
    // Remove trailing semicolon and excess whitespace
    let query = buffer.trim().trim_end_matches(';').trim();
    if query.is_empty() {
        buffer.clear();
        return;
    }

    // Detect OLAP queries (CALL statements): only output statistics, not per-row results
    let query_upper = query.to_uppercase();
    let is_olap = query_upper.starts_with("CALL");

    let start = Instant::now();
    match runtime.execute_query(query) {
        Ok(result) => {
            let elapsed = start.elapsed();
            if is_olap {
                print_olap_result(&result, elapsed);
            } else {
                print_result(&result);
            }
        }
        Err(e) => eprintln!("Error: {}", e),
    }
    println!();
    buffer.clear();
}

/**
 * @brief: Handle REPL meta-commands (starting with ':').
 * @param input: The complete meta-command line (including ':' prefix).
 * @param runtime: The current runtime.
 * @return: Returns ReplAction::Quit if the REPL should exit, otherwise Continue.
 */
fn handle_meta_command(input: &str, runtime: &metagdb::pipeline::Runtime) -> ReplAction {
    let (cmd, arg) = match input.find(' ') {
        Some(pos) => (&input[..pos], input[pos + 1..].trim()),
        None => (input, ""),
    };

    match cmd {
        ":help" | ":h" => {
            print_help();
        }
        ":quit" | ":q" | ":exit" => {
            return ReplAction::Quit;
        }
        ":explain" | ":e" => {
            if arg.is_empty() {
                eprintln!("Usage: :explain <query>");
            } else {
                match runtime.explain(arg) {
                    Ok(plan) => println!("{:#?}", plan),
                    Err(e) => eprintln!("Explain failed: {}", e),
                }
            }
        }
        ":schema" | ":s" => {
            print_schema(runtime);
        }
        _ => {
            eprintln!("Unknown command: {cmd}. Enter :help for help.");
        }
    }

    ReplAction::Continue
}

/**
 * @brief: Print REPL help information.
 */
fn print_help() {
    println!("metaGDB REPL Help");
    println!("=================");
    println!("  Enter Cypher statements directly (semicolon optional) to execute queries.");
    println!();
    println!("Meta Commands:");
    println!("  :help, :h          Show this help");
    println!("  :quit, :q, :exit   Exit REPL");
    println!("  :explain, :e <q>   Show physical execution plan for query");
    println!("  :schema, :s        Show current schema information");
    println!();
    println!("Examples:");
    println!("  MATCH (n) RETURN n");
    println!("  CREATE (n:Person {{name: 'Alice', age: 30}})");
    println!("  MATCH (a)-[:KNOWS]->(b) WHERE a.age > 30 RETURN b.name");
    println!("  CALL bfs(source=1)");
    println!("  :explain MATCH (n) RETURN n");
}

/**
 * @brief: Print current Schema information.
 * @param runtime: The current runtime.
 */
fn print_schema(runtime: &metagdb::pipeline::Runtime) {
    let schema = runtime.schema();
    println!("Schema Information");
    println!("===================");
    println!("Mode: {:?}", schema.schema_mode());
    println!();
    println!("Labels:");
    for l in schema.vertex_labels() {
        println!("  - {} (id={})", l.name, l.id.0);
    }
    println!();
    println!("Edge Types:");
    for e in schema.edge_types() {
        println!("  - {} (id={})", e.name, e.id.0);
    }
    println!();
    println!("Property Keys:");
    for pk in schema.property_keys() {
        println!("  - {} (id={})", pk.name, pk.id.0);
    }
}

// ============================================================
// Common Output Helpers
// ============================================================

/**
 * @brief: Visualize the query result stream in tabular form.
 * @param r: Query result stream reference.
 */
fn print_result(r: &ResultStream) {
    if r.rows.is_empty() {
        println!("(0 rows)");
        return;
    }

    let widths: Vec<usize> = r
        .schema
        .iter()
        .enumerate()
        .map(|(i, h)| {
            let max_cell = r
                .rows
                .iter()
                .map(|row| fmt_cell(&row[i]).len())
                .max()
                .unwrap_or(0);
            h.len().max(max_cell).max(8)
        })
        .collect();

    let header = r
        .schema
        .iter()
        .zip(&widths)
        .map(|(h, w)| format!("{:width$}", h, width = w))
        .collect::<Vec<_>>()
        .join(" | ");
    let sep = widths
        .iter()
        .map(|w| "-".repeat(*w))
        .collect::<Vec<_>>()
        .join("-+-");
    println!("{header}");
    println!("{sep}");
    for row in &r.rows {
        let line = row
            .iter()
            .zip(&widths)
            .map(|(cell, w)| format!("{:width$}", fmt_cell(cell), width = w))
            .collect::<Vec<_>>()
            .join(" | ");
        println!("{line}");
    }
    println!("({} rows)", r.rows.len());
}

/**
 * @brief: OLAP algorithm result statistics output — does not print per-row results, only
 *         statistical information.
 * @param r: Query result stream reference.
 * @param elapsed: Query execution elapsed time.
 */
fn print_olap_result(r: &ResultStream, elapsed: std::time::Duration) {
    println!(
        "Done: {} rows, {} cols ({:?})",
        r.rows.len(),
        r.schema.len(),
        elapsed
    );
    if !r.schema.is_empty() {
        println!("  Columns: {}", r.schema.join(", "));
    }
}

/**
 * @brief: Format a single result cell value as a string.
 * @param v: Result value reference.
 * @return: Formatted string.
 */
fn fmt_cell(v: &ResultValue) -> String {
    match v {
        ResultValue::Null => "NULL".into(),
        ResultValue::Bool(b) => b.to_string(),
        ResultValue::Int(i) => i.to_string(),
        ResultValue::Float(f) => f.to_string(),
        ResultValue::Text(s) => s.clone(),
        ResultValue::VertexRef(v) => format!("V({})", v.0),
        ResultValue::EdgeRef(e) => format!("E({})", e.0),
        ResultValue::Property(p) => fmt_prop(p),
        ResultValue::List(elems) => {
            let inner: Vec<String> = elems.iter().map(fmt_cell).collect();
            format!("[{}]", inner.join(", "))
        }
        ResultValue::Map(entries) => {
            let inner: Vec<String> = entries
                .iter()
                .map(|(k, v)| format!("{}:{}", fmt_cell(k), fmt_cell(v)))
                .collect();
            format!("{{{}}}", inner.join(", "))
        }
        ResultValue::Path(p) => {
            let inner: Vec<String> = p.objects.iter().map(fmt_cell).collect();
            format!("path[{}]", inner.join(", "))
        }
        ResultValue::PropertyElement(p) => {
            format!("{}={}@{}", p.key, fmt_cell(&p.value), fmt_cell(&p.element))
        }
        ResultValue::Set(elems) => {
            let mut inner: Vec<String> = elems.iter().map(fmt_cell).collect();
            inner.sort();
            format!("{{{}}}", inner.join(", "))
        }
    }
}

/**
 * @brief: Format a property value as a string.
 * @param p: Property value reference.
 * @return: Formatted string.
 */
fn fmt_prop(p: &PropertyValue) -> String {
    match p {
        PropertyValue::Null => "NULL".into(),
        PropertyValue::Bool(b) => b.to_string(),
        PropertyValue::Int(i) => i.to_string(),
        PropertyValue::Float(f) => f.to_string(),
        PropertyValue::Text(s) => s.clone(),
    }
}
